async function maybeLoadHls(v){
 if(!v.hlsUrl||typeof window==='undefined'||window.Hls||typeof document.createElement!=='function')return;
 try{
  const probe=await fetch('/assets/vendor/hls.min.js',{method:'HEAD',credentials:'same-origin'});
  if(!probe.ok)return; // Safe MP4 fallback if optional reviewed bundle is absent.
  await new Promise((resolve,reject)=>{
   const script=document.createElement('script');script.src='/assets/vendor/hls.min.js';script.async=true;
   script.onload=resolve;script.onerror=()=>reject(Error('HLS client failed to load'));
   document.head.appendChild(script);
  });
 }catch(e){console.warn('Adaptive HLS unavailable; using MP4 fallback',e.message)}
}
function destroyHls(){
 if(state.nextTimer){clearInterval(state.nextTimer);state.nextTimer=null}
 if(state.playerCleanup){try{state.playerCleanup()}catch{}state.playerCleanup=null}
 if(state.hlsController){try{state.hlsController.destroy()}catch{}state.hlsController=null}
}
function playerAvailability(){
 const native=typeof document.createElement==='function' ? document.createElement('video').canPlayType('application/vnd.apple.mpegurl') : '';
 return {hls:!!(window.Hls?.isSupported?.()||native),native:!!native};
}
function setPlayerMessage(message){const el=$('#player-status');if(el)el.textContent=message}
function playerTime(n){return duration(Math.max(0,Math.floor(n||0)))}
function displayTimelinePreview(frames,second){
 const box=$('#timeline-preview');if(!box)return;
 const selected=[...frames].reverse().find(f=>f.time<=second)||frames[0];
 if(selected){box.hidden=false;box.querySelector('img').src=selected.url;box.querySelector('span').textContent=playerTime(second)}
 else{box.hidden=false;box.querySelector('span').textContent=playerTime(second)}
}
function switchCaptionTrack(player,lang){
 for(let i=0;i<player.textTracks.length;i++)player.textTracks[i].mode=(lang!=='off'&&player.textTracks[i].language===lang)?'showing':'disabled';
}

function switchPlaybackQuality(player,newURL){
 // Only a limited set of validated URLs from the server-generated quality selector is accepted.
 const valid=[...document.querySelector('#playback-quality')?.options||[]].some(o=>o.value===newURL);
 if(!valid)throw Error('Unknown video quality');
 const time=player.currentTime||0,wasPlaying=!player.paused,speed=player.playbackRate,loop=player.loop;
 if(state.hlsController){try{state.hlsController.destroy()}catch{}state.hlsController=null}
 let completed=false;
 const complete=()=>{if(completed)return;completed=true;
   if(Number.isFinite(player.duration)){try{player.currentTime=Math.min(time,Math.max(0,player.duration-.05))}catch{}}
   player.playbackRate=speed;player.loop=loop;if(wasPlaying)player.play().catch(()=>{});
 };
 player.addEventListener('loadedmetadata',complete,{once:true});
 if(newURL.endsWith('.m3u8')&&window.Hls?.isSupported?.()){
   // Demux locally on the main thread: CSP deliberately forbids Blob scripts/workers.
   const hls=new window.Hls({enableWorker:false,maxBufferLength:30,maxLiveSyncPlaybackRate:1});state.hlsController=hls;
   let retries=0;
   hls.on(window.Hls.Events.ERROR,(_ev,data)=>{
     if(!data.fatal)return;
     if(retries++<2&&data.type===window.Hls.ErrorTypes.NETWORK_ERROR){setPlayerMessage('Retrying stream…');hls.startLoad();return}
     if(retries<=2&&data.type===window.Hls.ErrorTypes.MEDIA_ERROR){hls.recoverMediaError();return}
     const select=$('#playback-quality');const fallback=select?.options[0]?.value;
     if(fallback&&fallback!==newURL){select.value=fallback;switchPlaybackQuality(player,fallback);setPlayerMessage('Adaptive stream failed — playing MP4')}
   });
   hls.attachMedia(player);hls.on(window.Hls.Events.MEDIA_ATTACHED,()=>hls.loadSource(newURL));
 }else{player.src=newURL;player.load()}
}
