function updateCaptionAppearance(player){const size=localStorage.getItem('sa_caption_size')||'normal',contrast=localStorage.getItem('sa_caption_contrast')||'standard';player.classList.remove('captions-normal','captions-large','captions-extra','captions-high');player.classList.add(['normal','large','extra'].includes(size)?'captions-'+size:'captions-normal');if(contrast==='high')player.classList.add('captions-high')}
