 draw(`${titlebar('Watch Queue',`${out.items.length} videos · Private to your account`,out.items.length?'<button class="action-danger" data-action="queue-clear">Clear Queue</button>':'')}${out.items.length?`<div class="videogrid" id="queue-grid">${out.items.map((v,i)=>videoCard(v).replace('<article class="videocard">',`<article class="videocard" draggable="true" data-queue-id="${v.id}" aria-label="Drag to reorder ${esc(v.title)}">`).replace('</article>',actions(v,i)+'</article>')).join('')}</div>`:empty('Your queue is empty','Choose Add to Queue on a video page to start watching in order.',href('/videos/latest','Browse videos','action-yellow'))}`);
