 const [data,categories,analytics,studioCases,collaborators,retention,qoeSummary,uploadHealth,rightsReminders,playbackTrends]=await Promise.all([api('/api/studio/overview'),api('/api/categories'),api('/api/studio/analytics').catch(()=>null),api('/api/studio/compliance/cases').catch(()=>({items:[]})),api('/api/studio/collaborators').catch(()=>({owned:[],incoming:[]})),api('/api/studio/analytics/retention').catch(()=>null),api('/api/studio/analytics/qoe').catch(()=>null),api('/api/studio/upload-health').catch(()=>null),api('/api/studio/rights-reminders').catch(()=>null),api('/api/studio/analytics/playback-trends?days=30').catch(()=>null)]);const creator=data.creator;
