document.addEventListener('pointerover',event=>{const card=event.target.closest?.('.videocard');if(!card||card.contains(event.relatedTarget))return;const img=card.querySelector('img.thumb');if(img?.dataset.preview){img.dataset.posterSrcset=img.getAttribute('srcset')||'';img.removeAttribute('srcset');img.src=img.dataset.preview}});
document.addEventListener('pointerout',event=>{const card=event.target.closest?.('.videocard');if(!card||card.contains(event.relatedTarget))return;const img=card.querySelector('img.thumb');if(img?.dataset.original){img.src=img.dataset.original;if(img.dataset.posterSrcset)img.setAttribute('srcset',img.dataset.posterSrcset)}});
