document.addEventListener('input',event=>{
 if(event.target.id==='global-search'){
  clearTimeout(state.searchTimer);const needle=event.target.value.trim();const box=$('#search-suggestions');if(!box)return;if(!needle){box.hidden=true;return}
  const seq=++state.searchSeq;state.searchTimer=setTimeout(async()=>{try{const out=await api('/api/search/suggest?'+qs({q:needle}));if(seq!==state.searchSeq)return;const current=$('#search-suggestions');if(!current)return;current.innerHTML=suggestionsHTML(out,needle);current.hidden=false}catch{}},170)
 }
 if(event.target.id==='admin-filter'){const query=event.target.value.toLowerCase().trim();document.querySelectorAll('.smalltable tbody tr').forEach(row=>{row.hidden=!row.textContent.toLowerCase().includes(query)});}
 if(event.target.id==='category-search'){const q=event.target.value.trim();const p=new URLSearchParams(location.search);q?p.set('q',q):p.delete('q');history.replaceState(null,'','/categories?'+p.toString());document.querySelectorAll('.cat-section').forEach(node=>{const match=[...node.querySelectorAll('.chip')].filter(c=>c.textContent.toLowerCase().includes(q.toLowerCase()));node.style.display=match.length?'':'none';[...node.querySelectorAll('.chip')].forEach(c=>c.style.display=c.textContent.toLowerCase().includes(q.toLowerCase())?'':'none')})}
});
document.addEventListener('change',event=>{
 if(event.target.matches('.subscription-mode')){
  api('/api/me/subscriptions/'+event.target.dataset.channel+'/notifications',{method:'PATCH',body:JSON.stringify({mode:event.target.value})}).then(()=>toast('Notification preference saved')).catch(e=>toast(e.message));return;
 }
 if(['library-sort','library-filter'].includes(event.target.id)){
  const params=new URLSearchParams(location.search);
  const sort=$('#library-sort')?.value||'newest',filter=$('#library-filter')?.value||'all';
  params.set('sort',sort);params.set('filter',filter);goto(location.pathname+'?'+params);return;
 }
 if(event.target.id==='playback-quality'){const player=$('#video-player');if(!player)return;const newURL=event.target.value;if(!newURL.startsWith('/api/media/')&&!newURL.startsWith('/assets/'))return;switchPlaybackQuality(player,newURL);toast('Stream quality changed')}
 else if(event.target.id==='playback-speed'){const value=Number(event.target.value);const p=$('#video-player');if(p&&value>0&&value<=2){p.playbackRate=value;state.playerSpeed=value;localStorage.setItem('sa_speed',String(value))}}
 else if(event.target.id==='loop-video'){const p=$('#video-player');if(p)p.loop=event.target.checked}
 else if(event.target.id==='autoplay-video'){state.autoplay=event.target.checked;localStorage.setItem('sa_autoplay',String(state.autoplay))}
 else if(event.target.id==='country-filter'){const p=new URLSearchParams(location.search);event.target.value?p.set('country',event.target.value):p.delete('country');goto('/models?'+p.toString())}else if(event.target.id==='sorter'){const p=new URLSearchParams(location.search);p.set('sort',event.target.value);p.delete('page');goto(location.pathname+'?'+p.toString())}});
document.addEventListener('keydown',e=>{if(e.target.id==='global-search'&&e.key==='ArrowDown'){const first=$('#search-suggestions:not([hidden]) .suggest-item');if(first){e.preventDefault();first.focus()}}else if(e.target.matches?.('.suggest-item')&&['ArrowDown','ArrowUp'].includes(e.key)){const all=[...document.querySelectorAll('.suggest-item')];const i=all.indexOf(e.target);const next=all[i+(e.key==='ArrowDown'?1:-1)];if(next){e.preventDefault();next.focus()}}});
document.addEventListener('keydown',event=>{const tag=document.activeElement?.tagName;if(['INPUT','TEXTAREA','SELECT'].includes(tag)||event.ctrlKey||event.altKey||event.metaKey)return;const player=$('#video-player');if(!player)return;let changed=true;switch(event.key.toLowerCase()){
 case 'k':case ' ':event.preventDefault();if(player.paused)player.play().catch(()=>{});else player.pause();break;
 case 'j':player.currentTime=Math.max(0,player.currentTime-10);break;
 case 'l':player.currentTime=Math.min(player.duration||0,player.currentTime+10);break;
 case 'm':player.muted=!player.muted;break;
 case 'c':{const caps=$('#player-captions');if(caps){caps.value=caps.value==='off'?(caps.options[1]?.value||'off'):'off';switchCaptionTrack(player,caps.value)}break}
 case 'f':player.requestFullscreen?.().catch(()=>{});break;
 default:changed=false;
 }if(changed&&event.key!==' ')toast('Player shortcut: '+event.key.toUpperCase())});
let dragQueueId=null;
document.addEventListener('dragstart',e=>{const card=e.target.closest?.('[data-queue-id]');if(card){dragQueueId=Number(card.dataset.queueId);e.dataTransfer.effectAllowed='move'}});
document.addEventListener('dragover',e=>{if(dragQueueId&&e.target.closest?.('[data-queue-id]'))e.preventDefault()});
document.addEventListener('drop',async e=>{const target=e.target.closest?.('[data-queue-id]');if(!target||!dragQueueId)return;e.preventDefault();
 try{const queue=await api('/api/me/queue');const ids=queue.items.map(x=>x.id),from=ids.indexOf(dragQueueId),to=ids.indexOf(Number(target.dataset.queueId));
 if(from>=0&&to>=0&&from!==to){ids.splice(from,1);ids.splice(to,0,dragQueueId);await api('/api/me/queue/order',{method:'PATCH',body:JSON.stringify({videoIds:ids})});route()}}
 catch(err){toast(err.message)}finally{dragQueueId=null}});
document.addEventListener('dragend',()=>{dragQueueId=null});
window.addEventListener('popstate',route);
window.addEventListener('keydown',e=>{if(e.key==='Escape'){const m=$('#modal-root');if(m)m.remove();const drop=$('#search-suggestions');if(drop)drop.hidden=true}});
async function syncAccountPreferences(){if(!state.user){state.pauseHistory=false;state.saveSearches=false;return}try{const pref=await api('/api/me/preferences?expanded=1');state.pauseHistory=pref.pauseHistory;state.autoplay=pref.autoplayNext;state.saveSearches=pref.saveSearches;state.theme=pref.theme;state.locale=pref.locale}catch{}}
async function saveMemberPreferences(){if(!state.user)return;return api('/api/me/preferences',{method:'PATCH',body:JSON.stringify({pauseHistory:!!state.pauseHistory,autoplayNext:!!state.autoplay,saveSearches:!!state.saveSearches,theme:state.theme,locale:state.locale})})}
async function boot(){try{const [me,nets,csrf]=await Promise.all([api('/api/auth/me'),api('/api/networks'),api('/api/security/csrf')]);state.csrfToken=csrf.token;state.user=me.user;state.networks=nets;await syncAccountPreferences();await route()}catch(e){console.error(e);draw(empty('Unable to initialize application',e.message))}}
boot();
